package com.clavis.reader;
import android.app.Instrumentation;import android.content.Context;import java.util.*;import org.json.*;
final class StarterFeedChecks {
 static FeedStore.Feed feed(String kind,String url){FeedStore.Feed feed=new FeedStore.Feed();feed.kind=kind;feed.url=url;feed.title="Retained subscription";return feed;}
 static void run(Instrumentation test)throws Exception{Context c=test.getTargetContext();JSONArray catalog=FeedCatalog.catalog(c);int news=0,journals=0;HashSet<String> urls=new HashSet<>();for(int n=0;n<catalog.length();n++){JSONObject entry=catalog.getJSONObject(n);FeedPostChecks.check(urls.add(entry.getString("url")),"Starter source URLs unique");if(entry.getString("kind").equals("News")){news++;FeedPostChecks.check(entry.getString("contentMode").equals("full-feed"),"Every News default supplies full feed text");}if(entry.getString("kind").equals("Journals")){journals++;FeedPostChecks.check(entry.getString("contentMode").equals("open-access")&&!entry.optString("policy").isEmpty(),"Every journal default has reviewed open-access policy");}}
 FeedPostChecks.check(news==50&&journals==50,"Fifty verified News feeds and fifty cross-subject open journals");
 ArrayList<FeedStore.Feed> fresh=FeedCatalog.reconcile(c,Collections.emptyList(),catalog,false);for(FeedStore.Feed source:fresh)if(source.kind.equals("News")||source.kind.equals("Journals")){FeedPostChecks.check(!source.items.isEmpty()||!source.tags.isEmpty(),"Bundled source includes readable stories or topic metadata");FeedPostChecks.check(source.items.size()<=10,"Starter snapshots are bounded");if(source.fullText&&!source.items.isEmpty()){FeedPosts.State state=new FeedPosts.State(source,source.items.get(0));FeedPostChecks.check(state.loaded&&state.body.length()>120,"Full News RSS body is ready before any publisher request");}}
 FeedStore.Feed oldNews=feed("News","https://feeds.bbci.co.uk/news/rss.xml"),oldJournal=feed("Journals","https://jamanetwork.com/rss/site_3/67.xml"),custom=feed("News","https://custom.invalid/feed"),customJournal=feed("Journals","https://custom.invalid/journal"),podcast=feed("Podcasts","https://custom.invalid/audio"),open=feed("Journals","https://journals.plos.org/plosmedicine/feed/atom");FeedStore.Item marker=new FeedStore.Item();marker.title="Retained paper";open.items.add(marker);
 ArrayList<FeedStore.Feed> upgraded=FeedCatalog.reconcile(c,Arrays.asList(oldNews,oldJournal,custom,customJournal,podcast,open),catalog,true);FeedPostChecks.check(!upgraded.contains(oldNews)&&!upgraded.contains(oldJournal),"Only retired bundled subscriptions are removed on upgrade");FeedPostChecks.check(upgraded.contains(custom)&&upgraded.contains(customJournal)&&upgraded.contains(podcast),"Custom subscriptions and podcasts survive migration");FeedPostChecks.check(upgraded.contains(open)&&open.items.get(0)==marker&&open.access.equals("open-access"),"Existing open journals keep their cached papers");FeedPostChecks.check(upgraded.stream().filter(f->f.kind.equals("Podcasts")).count()==1,"Upgrade does not restore deleted podcast defaults");
 String rss="<rss xmlns:dc='http://purl.org/dc/elements/1.1/' xmlns:content='http://purl.org/rss/1.0/modules/content/'><channel><title>News</title><item><title>Story</title><dc:creator>Reporter Name</dc:creator><description>Summary</description><content:encoded><![CDATA[<p>Complete body from the publisher feed.</p>]]></content:encoded></item></channel></rss>";FeedStore.Feed parsed=FeedStore.parse(new java.io.ByteArrayInputStream(rss.getBytes(java.nio.charset.StandardCharsets.UTF_8)),"https://example.com/feed");FeedPostChecks.check(parsed.items.get(0).author.equals("Reporter Name")&&parsed.items.get(0).description.contains("Complete body"),"Full RSS body and original author survive parsing");
 String atom="<feed xmlns='http://www.w3.org/2005/Atom'><title>Journal</title><entry><title>Paper</title><author><name>First Author</name><uri>https://example.com/author</uri></author><author><name>Second Author</name></author><rights>CC BY 4.0</rights><summary>Abstract</summary></entry></feed>";parsed=FeedStore.parse(new java.io.ByteArrayInputStream(atom.getBytes(java.nio.charset.StandardCharsets.UTF_8)),"https://example.com/atom");FeedStore.Item paper=parsed.items.get(0);FeedPostChecks.check(paper.author.equals("First Author; Second Author")&&paper.rights.equals("CC BY 4.0"),"Atom author names and rights retained without treating profile URLs as names");FeedStore.Item saved=FeedStore.Item.from(paper.json());FeedPostChecks.check(saved.author.equals(paper.author)&&saved.rights.equals(paper.rights),"Article attribution survives persistence");
 }
}
